import{_ as n,C as l,o as t,c as o,j as i,E as r,a as d,a3 as e}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse('{"title":"3-hafta","description":"","frontmatter":{"title":"3-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"9-sinf (IoT)","link":"/9-sinf-iot/"},"n":3,"bob":"II-bob · Elektronika va Arduino bilan interaktiv interfeyslar","lessons":[{"g":7,"title":"7-dars: Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi","lead":"Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi","link":"/9-sinf-iot/hafta-03/dars-1","slide":"/slaydlar/9-sinf-iot/hafta-03/dars-1.html","test":"/slaydlar/9-sinf-iot/hafta-03/dars-1-test.html"},{"g":8,"title":"8-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism)","lead":"Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism)","link":"/9-sinf-iot/hafta-03/dars-2","slide":"/slaydlar/9-sinf-iot/hafta-03/dars-2.html","test":"/slaydlar/9-sinf-iot/hafta-03/dars-2-test.html"},{"g":9,"title":"9-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism)","lead":"Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism)","link":"/9-sinf-iot/hafta-03/dars-3","slide":"/slaydlar/9-sinf-iot/hafta-03/dars-3.html","test":"/slaydlar/9-sinf-iot/hafta-03/dars-3-test.html"}],"test":"/slaydlar/9-sinf-iot/hafta-03/hafta-test.html"}},"headers":[],"relativePath":"9-sinf-iot/hafta-03/index.md","filePath":"9-sinf-iot/hafta-03/index.md"}'),h={name:"9-sinf-iot/hafta-03/index.md"},u={class:"blk"},m={id:"uyga-vazifa",tabindex:"-1"};function k(f,a,b,g,c,y){const s=l("Icon");return t(),o("div",null,[i("div",u,[i("h2",m,[r(s,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=e('<p>Mazkur haftada o&#39;tilgan darslar bo&#39;yicha mustaqil bajarish uchun topshiriqlar. Har bir vazifa 20–30 daqiqaga mo&#39;ljallangan.</p><hr><h3 id="_7-dars-elektron-sxema-asosida-ikki-led-lampaning-ishlash-prinsipi-va-ulanishi" tabindex="-1">7-dars: Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi <a class="header-anchor" href="#_7-dars-elektron-sxema-asosida-ikki-led-lampaning-ishlash-prinsipi-va-ulanishi" aria-label="Permalink to &quot;7-dars: Elektron sxema asosida ikki LED lampaning ishlash prinsipi va ulanishi&quot;">​</a></h3><ol><li>Tinkercad-da Arduino Uno, Breadboard, 2 ta 220 Om rezistor hamda Qizil va Yashil LED dan iborat mustaqil parallel sxemani yig&#39;ing (Qizil — Pin 9, Yashil — Pin 11).</li><li>C++ tilida yo&#39;l harakati xavfsizligi mayoqchasini (Traffic Flasher) dasturlang: <ul><li>Qizil LED 3 marta tez miltillaydi (har biri 150 ms yoniq, 150 ms o&#39;chiq);</li><li>Yashil LED 3 marta tez miltillaydi (har biri 150 ms yoniq, 150 ms o&#39;chiq);</li><li>Ikkala LED 1 soniyaga o&#39;chib tanaffus qiladi va tsikl takrorlanadi.</li></ul></li><li>Nima uchun 3 ta LED ni 5V manbaga ketma-ket ulaganda ular yonmasligini kuchlanishlar yig&#39;indisi formulasi ($U = U_1 + U_2 + U_3$) orqali asoslab bering.</li></ol><hr><h3 id="_8-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-ishlash-1-qism" tabindex="-1">8-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism) <a class="header-anchor" href="#_8-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-ishlash-1-qism" aria-label="Permalink to &quot;8-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan ishlash (1-qism)&quot;">​</a></h3><ol><li>Arduino <code>D2</code> piniga va <code>GND</code> ga Push-button ulang. <code>pinMode(2, INPUT_PULLUP)</code> sozlamasidan foydalaning.</li><li>Tugma holatini o&#39;qib, Serial Monitorga chiqaruvchi dastur yozing.</li><li>Sxemaga Pin 9 dagi LEDni qo&#39;shing va quyidagi xavfsizlik signalizatsiyasi mantiqini tuzing: <ul><li>Tugma bo&#39;sh turganda (eshik yopiq deb hisoblanadi): LED o&#39;chiq bo&#39;lsin;</li><li>Tugma bosilganda (eshik buzib ochildi): LED tez miltillab xavf signali bersin va Serial Monitorga &quot;DIQQAT: Eshik ochildi!&quot; matni uzatilsin.</li></ul></li></ol><hr><h3 id="_9-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-interaktiv-interfeys-2-qism" tabindex="-1">9-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism) <a class="header-anchor" href="#_9-dars-arduino-uno-yordamida-led-indikatorlari-va-push-button-bilan-interaktiv-interfeys-2-qism" aria-label="Permalink to &quot;9-dars: Arduino UNO yordamida LED indikatorlari va push-button bilan interaktiv interfeys (2-qism)&quot;">​</a></h3><ol><li>1 ta Push-button va 1 ta LED yordamida to&#39;liq Toggle (trigged) kalitini dasturlang: tugma 1 marta bosilganda LED yonsin va yoniq qolsin, yana 1 marta bosilganda esa o&#39;chsin.</li><li>Dasturda nima sababdan <code>delay(50)</code> qo&#39;yilganini mexanik kontaktlarning dirillashi (Button Bounce) hodisasi misolida tushuntiring.</li><li>Sxemaga ikkinchi tugma va ikkinchi LED qo&#39;shing. Biri Qizil chiroqni, ikkinchisi Yashil chiroqni mustaqil boshqarsin. Ikkala chiroq bir-biriga xalaqit bermasdan ishlashini simulyatsiyada ko&#39;rsating.</li></ol><hr>',11))])])}const v=n(h,[["render",k]]);export{q as __pageData,v as default};
